    /**
     * Tests getting all PaymentOrders.
     *
     * @return    Collection
     */
    public List<PaymentOrder> testGetAll() throws Throwable {
    LOGGER.info( "PaymentOrderTest:testGetAll() - Retrieving Collection of PaymentOrders:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PaymentOrder : " );
    List<PaymentOrder> collection  = null;

    try {
        // call the static get method on the PaymentOrderService
        collection = service.getAllPaymentOrder();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PaymentOrder currEntity  = null;
            Iterator<PaymentOrder> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPaymentOrderId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

